WITH t AS (SELECT FanID,COUNT(DISTINCT MatchID) MatchesAttended FROM FactTicketSales GROUP BY FanID), e AS (SELECT FanID,SUM(EngagementActions) EngagementActions,SUM(Sessions) Sessions FROM FactDigitalEngagement GROUP BY FanID) SELECT d.FanID,CASE WHEN COALESCE(t.MatchesAttended,0)>=2 AND d.IsMember=1 THEN 'Repeat Buyer' WHEN COALESCE(t.MatchesAttended,0)>=1 THEN 'Ticket Buyer' WHEN d.IsMember=1 THEN 'Member' WHEN COALESCE(e.EngagementActions,0)>=8 THEN 'Engaged' WHEN COALESCE(e.Sessions,0)>=1 THEN 'Digital Visitor' ELSE 'New/Low Activity' END LifecycleStage FROM DimFan d LEFT JOIN t ON d.FanID=t.FanID LEFT JOIN e ON d.FanID=e.FanID;
